--
-- Table structure for table `reports`
--

DROP TABLE IF EXISTS `reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reports` (
  `id` int NOT NULL AUTO_INCREMENT,
  `reference` varchar(255) DEFAULT NULL,
  `form_number` varchar(255) DEFAULT NULL,
  `report_type` varchar(255) DEFAULT NULL,
  `aircraft_registration` varchar(255) DEFAULT NULL,
  `type_of_operation` varchar(255) DEFAULT NULL,
  `date_of_accident` date DEFAULT NULL,
  `time_of_accident` time DEFAULT NULL,
  `location_description` text,
  `gps_direction_1` varchar(1) DEFAULT NULL,
  `gps_degrees_1` int DEFAULT NULL,
  `gps_minutes_1` int DEFAULT NULL,
  `gps_seconds_1` decimal(10,2) DEFAULT NULL,
  `gps_direction_2` varchar(1) DEFAULT NULL,
  `gps_degrees_2` int DEFAULT NULL,
  `gps_minutes_2` int DEFAULT NULL,
  `gps_seconds_2` decimal(10,2) DEFAULT NULL,
  `elevation_feet` int DEFAULT NULL,
  `meteorological_info` text,
  `wind_direction_degrees` int DEFAULT NULL,
  `wind_speed_knots` int DEFAULT NULL,
  `temperature_celsius` float DEFAULT NULL,
  `visibility` varchar(255) DEFAULT NULL,
  `people_onboard` int DEFAULT NULL,
  `injured` int DEFAULT NULL,
  `killed` int DEFAULT NULL,
  `pilot_age` int DEFAULT NULL,
  `pilot_licence_type` varchar(255) DEFAULT NULL,
  `pilot_ratings` varchar(255) DEFAULT NULL,
  `pilot_restrictions` varchar(255) DEFAULT NULL,
  `medical_expiry_date` date DEFAULT NULL,
  `licence_valid` varchar(10) DEFAULT NULL,
  `total_flying_hours` float DEFAULT NULL,
  `flying_hours_last_90_days` float DEFAULT NULL,
  `hours_on_type` float DEFAULT NULL,
  `hours_on_type_last_90_days` float DEFAULT NULL,
  `airframe_manufacturer` varchar(255) DEFAULT NULL,
  `airframe_model` varchar(255) DEFAULT NULL,
  `airframe_serial` varchar(255) DEFAULT NULL,
  `airframe_manufacture_year` int DEFAULT NULL,
  `airframe_total_hours` float DEFAULT NULL,
  `last_mpi_date` date DEFAULT NULL,
  `last_mpi_hours` float DEFAULT NULL,
  `engine1_type` varchar(255) DEFAULT NULL,
  `engine1_serial` varchar(255) DEFAULT NULL,
  `engine1_hours_new` int DEFAULT NULL,
  `engine1_hours_overhaul` int DEFAULT NULL,
  `probable_cause` text,
  `contributing_factors` text,
  `investigation_notes` text,
  `coa_expiration` date DEFAULT NULL,
  `maintenance_compliant` varchar(10) DEFAULT NULL,
  `mass_balance_ok` varchar(10) DEFAULT NULL,
  `engine_failure` varchar(10) DEFAULT NULL,
  `airframe_failure` varchar(10) DEFAULT NULL,
  `people_on_board` int DEFAULT NULL,
  `pilot_license_type` varchar(255) DEFAULT NULL,
  `pilot_age_` int DEFAULT NULL,
  `pilot_license_valid` varchar(10) DEFAULT NULL,
  `total_flying_hours_` float DEFAULT NULL,
  `hours_on_type_` float DEFAULT NULL,
  `departure` varchar(255) DEFAULT NULL,
  `destination` varchar(255) DEFAULT NULL,
  `weather_wind` varchar(255) DEFAULT NULL,
  `weather_temp` varchar(255) DEFAULT NULL,
  `weather_cloud` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
